import numpy as np


def design(feats):
    ids, X, y = tuple(feats.ids), np.asarray(feats.x, float), np.asarray(feats.y)
    n, p = X.shape
    pos = y == 1

    def tstat(Z, m):  # Welch t of each column of Z vs binary mask m
        a, b = Z[m], Z[~m]
        v = a.var(0, ddof=1) / m.sum() + b.var(0, ddof=1) / (len(m) - m.sum())
        return (a.mean(0) - b.mean(0)) / np.sqrt(v + 1e-12)

    t = tstat(X, pos)
    C = np.atleast_2d(np.corrcoef(X, rowvar=False)); np.fill_diagonal(C, 0.0)
    root = list(range(p))

    def find(i):
        while root[i] != i: root[i] = root[root[i]]; i = root[i]
        return i

    for i in range(p):
        for j in np.flatnonzero(np.abs(C[i]) >= 0.6): root[find(i)] = find(j)
    groups = {}
    for i in range(p): groups.setdefault(find(i), []).append(i)

    reps, glist, scores, wmap = {}, [], [], {}
    for g, mem in groups.items():
        if len(mem) == 1: reps[g] = mem[0]; continue
        sub = C[np.ix_(mem, mem)]
        w = np.linalg.eigh(sub)[1][:, -1]
        if np.corrcoef(X[:, mem] @ w, X[:, mem].mean(1))[0, 1] < 0: w = -w
        reps[g] = mem[int(np.argmax(np.abs(sub).sum(0)))]
        glist.append(g); scores.append(X[:, mem] @ w)
        wmap[g] = {ids[mem[k]]: float(w[k]) for k in range(len(mem))}
    S = np.array(scores).T if scores else np.empty((n, 0))
    pairs = [(a, b) for a in range(p) for b in range(a + 1, p) if find(a) != find(b)]
    P = np.column_stack([X[:, a] * X[:, b] for a, b in pairs]) if pairs else np.empty((n, 0))
    Z = np.hstack([X, S])
    tA = tstat(Z, pos); tP = tstat(P, pos) if len(pairs) else np.zeros(0)
    obsA = np.abs(tA).max(); obsP = np.abs(tP).max() if len(tP) else 0.0
    rng = np.random.default_rng(0); geA = geP = 0
    for _ in range(400):
        m = rng.permutation(y) == 1
        geA += np.abs(tstat(Z, m)).max() >= obsA
        geP += len(tP) and np.abs(tstat(P, m)).max() >= obsP
    hitA = (geA + 1) / 401 <= 0.05; hitP = bool(len(tP)) and (geP + 1) / 401 <= 0.05
    columns = []
    for i in np.argsort(-np.abs(t)):
        if ids[reps[find(i)]] not in columns: columns.append(ids[reps[find(i)]])
        if len(columns) >= 8: break
    pk = [k for k in np.argsort(-np.abs(tP)) if abs(tP[k]) >= 3.5][:4] if hitP else []
    products = [(ids[reps[find(pairs[k][0])]], ids[reps[find(pairs[k][1])]]) for k in pk]
    loadings = {}
    if glist:
        si = p + int(np.argmax(np.abs(tA[p:])))
        if abs(tA[si]) >= 2.5: loadings = wmap[glist[si - p]]
    if not (hitA or hitP):
        return Design(drivers=(), columns=tuple(columns), products=tuple(products), loadings=loadings)
    tz = np.concatenate([tA, tP])
    cmap = ([(reps[find(i)],) for i in range(p)] + [(reps[g],) for g in glist] +
            [(reps[find(a)], reps[find(b)]) for a, b in pairs])
    drivers, seen = [], set()
    for i in np.argsort(-np.abs(tz)):
        if abs(tz[i]) < 2.0 or len(drivers) >= MAX_DRIVERS: break
        for u in cmap[i]:
            if ids[u] not in seen and len(drivers) < MAX_DRIVERS: drivers.append(ids[u]); seen.add(ids[u])
    drivers = drivers or (ids[reps[find(int(np.argmax(np.abs(tz[:p]))))]],)
    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

